// Normalizes all channels into the canonical RescueFlow Schema
const item = $input.item.json;
let source = 'web';
let sender = 'Anonymous Citizen';
let messageText = '';
let locationHint = '';
let metadata = {};

if (item.message && item.message.text) {
  source = 'telegram';
  sender = item.message.from ? ('@' + (item.message.from.username || item.message.from.first_name)) : 'Telegram User';
  messageText = item.message.text.replace(/^\/report\s*/i, '');
  metadata = { chat_id: item.message.chat ? item.message.chat.id : null };
} else if (item.from && item.subject) {
  source = 'email';
  sender = item.from.value ? item.from.value[0].address : (item.from.text || 'Email User');
  messageText = item.text || item.html || item.subject;
  metadata = { subject: item.subject };
} else {
  source = item.source || 'web';
  sender = item.sender || item.name || 'Web Citizen';
  messageText = item.message || '';
  locationHint = item.location || item.location_hint || '';
  metadata = item.metadata || {};
}

const messageId = item.message_id || 'MSG-' + Math.random().toString(36).substring(2, 10).toUpperCase();

return {
  message_id: messageId,
  source: source,
  sender: sender,
  message: messageText.trim(),
  location_hint: locationHint,
  timestamp: item.timestamp || new Date().toISOString(),
  metadata: metadata
};

